def test_uses_initial_strategy():
    def fastest(distance):
        return distance / 2
    router = Router(fastest)
    assert router.plan(100) == 50, 'plan must delegate to the strategy passed to __init__'

def test_swaps_strategy_at_runtime():
    def fastest(distance):
        return distance / 2
    def cheapest(distance):
        return distance * 1.5
    router = Router(fastest)
    router.set_strategy(cheapest)
    assert router.plan(10) == 15, 'after set_strategy, plan must use the new strategy, not the old one'

def test_can_swap_back():
    def a(distance):
        return distance + 1
    def b(distance):
        return distance + 2
    router = Router(a)
    router.set_strategy(b)
    router.set_strategy(a)
    assert router.plan(0) == 1, 'set_strategy must allow swapping back to a previously used strategy'

